import java.util.*;

public class Ex07DependencyMediation {
    record Dep(String group, String artifact, String version, int depth) {}

    public static void main(String[] args) {
        List<Dep> tree = List.of(
                new Dep("org.slf4j", "slf4j-api", "2.0.9", 2),
                new Dep("org.slf4j", "slf4j-api", "1.7.36", 3),
                new Dep("com.fasterxml.jackson.core", "jackson-databind", "2.15.2", 2),
                new Dep("com.fasterxml.jackson.core", "jackson-databind", "2.9.10", 1));

        Map<String, Dep> resolved = new LinkedHashMap<>();
        for (Dep d : tree) {
            String ga = d.group() + ":" + d.artifact();
            Dep cur = resolved.get(ga);
            if (cur == null || d.depth() < cur.depth()) resolved.put(ga, d);
        }

        System.out.println("resolved dependency versions (nearest wins):");
        for (Dep d : resolved.values()) {
            System.out.println("  " + d.group() + ":" + d.artifact()
                    + " -> " + d.version() + "   (depth=" + d.depth() + ")");
        }
        System.out.println("resolved artifacts = " + resolved.size());
    }
}
